#e4f8eb;color:#23623d}.notice.error{display:block;background:#fff0f0;color:#982e38}.reservation-success{display:block;background:linear-gradient(145deg,#fff0f7,#fff8df);color:var(--ink);border:2px solid #f2b3ca;text-align:center;padding:24px 16px;box-shadow:0 12px 25px #e3367920}.reservation-success h3{font-size:28px;color:var(--berry);margin-bottom:8px}.reservation-success .ticket-link{display:block;margin:12px auto 10px}.reservation-success .restart-btn{width:auto;background:var(--ink);box-shadow:none;font-size:13px;padding:10px 15px}.foot{padding:25px 0 48px;color:var(--muted);font-size:13px;text-align:center}.pdf-note{font-size:12px;color:var(--muted);margin-top:13px}
        .success-overlay{position:fixed;inset:0;z-index:1000;display:none;align-items:center;justify-content:center;padding:22px;background:#40243ccc;backdrop-filter:blur(5px)}.success-overlay.is-visible{display:flex}.success-card{width:min(620px,100%);border:4px solid #f6b73c;border-radius:30px;padding:42px 28px;text-align:center;background:linear-gradient(145deg,#fff5fb,#fff7da);box-shadow:0 25px 80px #160f1966;animation:successPop .35s ease-out}.success-card .success-confetti{font-size:48px;line-height:1;margin-bottom:12px}.success-card h2{font-size:clamp(34px,7vw,58px);color:var(--berry);margin-bottom:12px}.success-card p{font-size:20px;line-height:1.45;margin:8px 0;color:var(--ink)}.success-card .reservation-number{display:inline-block;margin:14px 0;padding:12px 20px;border-radius:14px;background:#40243c;color:#fff;font-size:26px;font-weight:800;letter-spacing:.04em}.success-card .ticket-link{display:block;font-size:18px;margin:12px 0 18px}.success-card .restart-btn{width:auto;background:var(--berry);box-shadow:none;margin:6px}.success-card .close-success{width:auto;background:transparent;color:var(--ink);box-shadow:none;text-decoration:underline;padding:8px 14px}.success-card .success-question{font-weight:700;font-size:17px;margin-top:10px}@keyframes successPop{from{opacity:0;transform:scale(.82) translateY(18px)}to{opacity:1;transform:scale(1) translateY(0)}}
