<script>
const CSRF = <?= json_encode($csrf) ?>;
const DATA = {
  models: [
    {id:'mini',name:'Minicake',sub:'18 cm · 8 cm alto',base:2000,img:'assets/cakes_catalogo/pdf-image-29.png',kind:'custom'},
    {id:'cake22',name:'Cake de 22 cm',sub:'22 cm · 8 cm alto',base:3500,img:'assets/cakes_catalogo/pdf-image-81.png',kind:'custom'},
    {id:'two',name:'Cake de 2 pisos',sub:'22 cm + 18 cm',base:8000,img:'assets/cakes_catalogo/pdf-image-119.png',kind:'custom'},
    {id:'three',name:'Cake de 3 pisos',sub:'Aproximadamente 20 personas',base:15700,img:'assets/cakes_catalogo/cake-3-pisos-descendente.png',kind:'flavor'},
    {id:'large',name:'Cake 30 × 40',sub:'25–30 personas',base:9500,img:'assets/cakes_catalogo/cake-30x40-rosa.png',kind:'flavor'}
  ],
  flavors:['Vainilla','Chocolate','Fresa','Mantecado'],
  fillings:['Vainilla','Chocolate','Fresa','Mantecado','Limón','Frutas mixtas'],
  meringueColors:['Blanco','Azul','Verde','Rojo','Rosado','Naranja','Amarillo','Morado','Celeste','Negro'],
  coverage:{mini:[['Merengue incluido',0],['Nata',2000],['Ganache de chocolate',3000]],cake22:[['Merengue incluido',0],['Nata',4000],['Ganache de chocolate',5000]],two:[['Merengue incluido',0],['Nata',6000],['Ganache de chocolate',8000]]},
  extras:{mini:[['Cobertura de bombón',500],['Fanguito',800],['Nutella',900],['Confituras mixtas',1000]],cake22:[['Cobertura de bombón',800],['Fanguito',1200],['Nutella',1400],['Confituras mixtas',1500]],two:[['Cobertura de bombón',1400],['Fanguito',2100],['Nutella',2400],['Confituras mixtas',2600]]},
  direct:{three:[['Fresa',15700],['Vainilla',16100],['Vainilla chips',16600],['Chocolate',17000],['Chocomaní',17500],['Bombón',18100],['Fresa bombón',18500],['Tres delicias',18900]],large:[['Tres delicias',11500],['Fresa bombón',11200],['Bombón',11000],['Frambuesa',10700],['Chocomaní',10500],['Chocolate',10200],['Vainilla chips',9900],['Vainilla',9700],['Fresa',9500]]}
};
let selected={model:'mini',flavor:'Vainilla',filling:'Fresa',coverage:'Merengue incluido',extra:'Sin extra',meringueColor:'Blanco'};
let cart=[];
let orderRequestId=crypto.randomUUID().replace(/-/g,'');
const money=n=>Number(n||0).toLocaleString('es-CU',{maximumFractionDigits:0})+' CUP';
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
function setCakeCount(value){const count=Math.max(0,parseInt(value,10)||0);document.getElementById('cakeCount').textContent=String(count).padStart(4,'0')}
async function loadCakeCount(){try{const r=await fetch('cakes_builder_api.php?visit=1',{cache:'no-store'});const d=await r.json();if(r.ok&&d.status==='success')setCakeCount(d.count)}catch(e){}}
function iconFor(label){const text=String(label).toLowerCase();if(text.includes('vainilla'))return '🍦';if(text.includes('limón'))return '🍋';if(text.includes('frutas mixtas'))return '🍇';if(text.includes('chocolate')||text.includes('chocomaní')||text.includes('nutella')||text.includes('ganache'))return '🍫';if(text.includes('fresa')||text.includes('frambuesa'))return '🍓';if(text.includes('mantecado'))return '🧈';if(text.includes('merengue')||text.includes('nata'))return '🍥';if(text.includes('bombón'))return '🍬';if(text.includes('fanguito'))return '🍯';if(text.includes('confitura'))return '🍭';if(text.includes('tres delicias'))return '🍰';if(text.includes('sin extra'))return '✨';return '🎂'}
function choice(name, value, label, price=0, checked=false){return `<label class="choice"><input type="radio" name="${name}" value="${esc(value)}" ${checked?'checked':''}><span class="choice-icon" aria-hidden="true">${iconFor(label)}</span><strong>${esc(label)}</strong>${price?`<small>+${money(price)}</small>`:'<small>Incluido</small>'}</label>`}
function meringueChoice(color){const selectedColor=color===selected.meringueColor?' is-selected':'';return `<button type="button" class="meringue-swatch${selectedColor}" data-meringue-color="${esc(color)}" aria-pressed="${color===selected.meringueColor?'true':'false'}"><span class="meringue-dot" style="background:${meringueColorHex(color)}"></span><span>${esc(color)}</span></button>`}
function modelCards(){document.getElementById('models').innerHTML=DATA.models.map((m,i)=>`<label class="choice model"><input type="radio" name="model" value="${m.id}" ${i===0?'checked':''}><img src="${m.img}" alt="${esc(m.name)}"><div class="model-copy"><strong>${esc(m.name)}</strong><small>${esc(m.sub)} · desde ${money(m.base)}</small></div></label>`).join('');document.querySelectorAll('[name=model]').forEach(e=>e.addEventListener('change',()=>{selected.model=e.value;const m=DATA.models.find(x=>x.id===selected.model);selected.flavor=m.kind==='flavor'?DATA.direct[m.id][0][0]:'Vainilla';selected.filling='Chocolate';selected.coverage='Merengue incluido';selected.extra='Sin extra';renderSteps();update()}))}
function renderSteps(){let m=DATA.models.find(x=>x.id===selected.model);let el=document.getElementById('customSteps');if(m.kind==='flavor'){el.innerHTML=`<div class="step-title"><span class="num">2</span><h2>Elige el sabor</h2></div><p class="hint">Selecciona una opción del catálogo.</p><div class="choices">${DATA.direct[m.id].map((x,i)=>choice('flavor',x[0],x[0],0,i===0)).join('')}</div>`;document.querySelectorAll('[name=flavor]').forEach(e=>e.addEventListener('change',()=>{selected.flavor=e.value;update()}));return}el.innerHTML=`<div class="step-title"><span class="num">2</span><h2>La panetela</h2></div><p class="hint">Escoge el sabor.</p><div class="choices">${DATA.flavors.map((x,i)=>choice('flavor',x,x,0,i===0)).join('')}</div><div class="step-title" style="margin-top:24px"><span class="num">3</span><h2>El relleno</h2></div><p class="hint">Elige tu crema favorita.</p><div class="choices">${DATA.fillings.map((x,i)=>choice('filling',x,x,0,x===selected.filling)).join('')}</div><div class="step-title" style="margin-top:24px"><span class="num">4</span><h2>Cobertura y extras</h2></div><p class="hint">El merengue está incluido; puedes cambiarlo o añadir un toque especial.</p><div class="choices">${DATA.coverage[m.id].map((x,i)=>choice('coverage',x[0],x[0],x[1],i===0)).join('')}</div><div class="field" style="margin-top:12px"><label>Color del merengue</label><div class="meringue-palette" role="radiogroup" aria-label="Color del merengue">${DATA.meringueColors.map(meringueChoice).join('')}</div></div><div class="choices" style="margin-top:12px">${[['Sin extra',0],...DATA.extras[m.id]].map((x,i)=>choice('extra',x[0],x[0],x[1],i===0)).join('')}</div>`;['flavor','filling','coverage','extra'].forEach(n=>document.querySelectorAll('[name='+n+']').forEach(e=>e.addEventListener('change',()=>{selected[n]=e.value;update()})));document.querySelectorAll('[data-meringue-color]').forEach(e=>e.addEventListener('click',()=>{selected.meringueColor=e.dataset.meringueColor;document.querySelectorAll('[data-meringue-color]').forEach(b=>{const active=b.dataset.meringueColor===selected.meringueColor;b.classList.toggle('is-selected',active);b.setAttribute('aria-pressed',active?'true':'false')});update()}))}
function selectedPrice(){let m=DATA.models.find(x=>x.id===selected.model);if(m.kind==='flavor') return DATA.direct[m.id].find(x=>x[0]===selected.flavor)?.[1]??m.base;let cov=DATA.coverage[m.id].find(x=>x[0]===selected.coverage)?.[1]??0;let ext=DATA.extras[m.id].find(x=>x[0]===selected.extra)?.[1]??0;return m.base+cov+ext}
function flavorPalette(label){const text=String(label||'').toLowerCase();if(text.includes('chocolate')||text.includes('chocomaní')||text.includes('nutella')||text.includes('ganache'))return {body:'#8e4a3e',fill:'#5a2928',cream:'#fff6fa'};if(text.includes('fresa')||text.includes('frambuesa'))return {body:'#f2a0ae',fill:'#e95c83',cream:'#fff1f6'};if(text.includes('limón'))return {body:'#e8dc72',fill:'#b6b93b',cream:'#fffbd2'};if(text.includes('frutas mixtas'))return {body:'#dba0c8',fill:'#8fb8db',cream:'#fff4fb'};if(text.includes('mantecado'))return {body:'#e9bd63',fill:'#d99742',cream:'#fff1c9'};if(text.includes('vainilla'))return {body:'#f2d39a',fill:'#e8a96f',cream:'#fffaf0'};return {body:'#efc78a',fill:'#d88a59',cream:'#fff5e7'}}
function previewSprinkles(x,y,w,count=8){const colors=['#e33679','#f6b73c','#55aee8','#67bb87','#9c6ade'];let out='';for(let i=0;i<count;i++){const px=x+14+((i*37+Math.round(w))%(Math.max(22,w-28)));const py=y+8+((i*17+Math.round(w))%Math.max(12,Math.round(w*.42)));out+=`<circle cx="${px}" cy="${py}" r="2.2" fill="${colors[i%colors.length]}"/>`}return out}
function cakeExtraCoating(x,y,w,h,label){const text=String(label||'').toLowerCase();if(text.includes('cobertura de bombón'))return `<path d="M ${x+5} ${y+8} Q ${x+w*.5} ${y-5} ${x+w-5} ${y+8} L ${x+w-7} ${y+h-7} Q ${x+w*.82} ${y+h-13} ${x+w*.7} ${y+h-5} Q ${x+w*.57} ${y+h+2} ${x+w*.46} ${y+h-6} Q ${x+w*.32} ${y+h-15} ${x+w*.2} ${y+h-6} Q ${x+w*.1} ${y+h-1} ${x+5} ${y+h-9} Z" fill="#5a2928" opacity=".94"/>`;
if(text.includes('fanguito'))return `<path d="M ${x+5} ${y+8} Q ${x+w*.5} ${y-5} ${x+w-5} ${y+8} L ${x+w-8} ${y+h-9} Q ${x+w*.78} ${y+h-15} ${x+w*.67} ${y+h-5} Q ${x+w*.54} ${y+h+3} ${x+w*.4} ${y+h-7} Q ${x+w*.25} ${y+h-14} ${x+5} ${y+h-8} Z" fill="#b86b32" opacity=".92"/>`;
return ''}
function cakeExtraTop(x,y,w,label){const text=String(label||'').toLowerCase(), cx=x+w/2;if(text.includes('confituras mixtas'))return `<g class="treats"><circle cx="${x+w*.22}" cy="${y+2}" r="7" fill="#e33679" stroke="#fff" stroke-width="2"/><path d="M ${x+w*.22} ${y-5} v-16" stroke="#6d3545" stroke-width="2"/><circle cx="${x+w*.48}" cy="${y-3}" r="6" fill="#f6b73c"/><rect x="${x+w*.65}" y="${y-12}" width="15" height="12" rx="3" fill="#c98d55" transform="rotate(-12 ${x+w*.65} ${y-12})"/><circle cx="${x+w*.83}" cy="${y+1}" r="6" fill="#55aee8"/><path d="M ${x+w*.78} ${y-2} q 8-8 16 0" fill="none" stroke="#e33679" stroke-width="3"/></g>`;
if(text.includes('nutella'))return `<path d="M ${x+w*.26} ${y+2} C ${x+w*.34} ${y-9} ${x+w*.48} ${y+12} ${x+w*.58} ${y} S ${x+w*.8} ${y-8} ${x+w*.72} ${y+6}" fill="none" stroke="#a86434" stroke-width="7" stroke-linecap="round" opacity=".95"/><path d="M ${x+w*.29} ${y+2} C ${x+w*.38} ${y-5} ${x+w*.48} ${y+8} ${x+w*.57} ${y}" fill="none" stroke="#d18a4f" stroke-width="2" stroke-linecap="round"/>`;
return ''}
function meringueColorHex(label){const colors={Blanco:'#fffafc',Azul:'#72b7e8',Verde:'#73c68a',Rojo:'#e35a62',Rosado:'#f28cac',Naranja:'#f3a04f',Amarillo:'#f1d85a',Morado:'#a67bd6',Celeste:'#8ad9e8',Negro:'#4d4550'};return colors[label]||colors.Blanco}
function renderCakePreview(){const m=DATA.models.find(x=>x.id===selected.model);const base=flavorPalette(selected.flavor);const filling=flavorPalette(selected.filling);const coverageText=String(selected.coverage||'').toLowerCase();const extraText=String(selected.extra||'').toLowerCase();const isNata=coverageText.includes('nata');const frosting=coverageText.includes('ganache')?'#5a2928':isNata?'#fff8fb':coverageText.includes('merengue')?meringueColorHex(selected.meringueColor):base.cream;const frostingFilter=isNata?' filter="url(#nataSoft)"':'';const tierCount=m.id==='three'?3:m.id==='two'?2:1;const rectangular=m.id==='large';const isMini=m.id==='mini';const widths=rectangular?[238]:tierCount===3?[198,150,108]:tierCount===2?[190,138]:isMini?[165]:[220];const heights=tierCount===3?[39,37,35]:tierCount===2?[48,44]:isMini?[48]:[62];const y=tierCount===3?[122,82,46]:tierCount===2?[111,64]:isMini?[107]:[93];const center=150;let tiers='';for(let i=0;i<tierCount;i++){const w=widths[i],h=heights[i],x=center-w/2,yy=y[i],rx=rectangular?15:Math.min(24,w/5);const topY=yy;const bandY=yy+h*.52;const coating=cakeExtraCoating(x,yy,w,h,extraText);const topDecor=cakeExtraTop(x,yy,w,extraText);tiers+=`<g><rect x="${x}" y="${yy}" width="${w}" height="${h}" rx="${rx}" fill="${base.body}" stroke="#6d3545" stroke-width="3"/><rect x="${x}" y="${yy}" width="${w}" height="${h}" rx="${rx}" fill="url(#cakeShine)"/><rect x="${x+4}" y="${bandY}" width="${w-8}" height="${Math.max(8,h*.18)}" rx="4" fill="${filling.fill}" opacity=".95"/>${coating}<path d="M ${x+4} ${topY+5} Q ${center} ${topY-10} ${x+w-4} ${topY+5} L ${x+w-4} ${topY+13} Q ${center} ${topY+1} ${x+4} ${topY+13} Z" fill="${frosting}" stroke="#d77b98" stroke-width="2"${frostingFilter}/>${previewSprinkles(x,yy,w,rectangular?12:7)}${topDecor}<path d="M ${x+10} ${yy+h-7} Q ${x+w*.25} ${yy+h+3} ${x+w*.5} ${yy+h-7} T ${x+w-10} ${yy+h-7}" fill="none" stroke="${frosting}" stroke-width="7" stroke-linecap="round"${frostingFilter}/></g>`}const bottom=tiers;const face=tierCount===1||tierCount===2?`<g fill="#40243c"><circle cx="139" cy="${y[0]+(heights[0]*.72)}" r="3"/><circle cx="161" cy="${y[0]+(heights[0]*.72)}" r="3"/></g><path d="M 143 ${y[0]+(heights[0]*.82)} Q 150 ${y[0]+(heights[0]*.91)} 157 ${y[0]+(heights[0]*.82)}" fill="none" stroke="#40243c" stroke-width="2.5" stroke-linecap="round"/>`:'';document.getElementById('cakePreview').innerHTML=`<svg viewBox="0 0 300 170" role="img" aria-label="Vista previa animada del ${esc(m.name)}"><defs><filter id="nataSoft"><feGaussianBlur stdDeviation="1.15"/></filter><linearGradient id="cakeShine" x1="0" x2="1" y1="0" y2="0"><stop offset="0" stop-color="#fff" stop-opacity=".36"/><stop offset=".42" stop-color="#fff" stop-opacity=".03"/><stop offset="1" stop-color="#492334" stop-opacity=".24"/></linearGradient></defs><ellipse cx="150" cy="157" rx="${rectangular?116:isMini?78:96}" ry="8" fill="#d9a6b7" opacity=".35"/><g class="cake-bob">${bottom}${face}<g class="cake-sparkle" fill="#f6b73c"><path d="M 32 42 l 3 7 l 7 3 l-7 3 l-3 7 l-3-7 l-7-3 l7-3 z"/><path d="M 265 65 l 2 5 l5 2 l-5 2 l-2 5 l-2-5 l-5-2 l5-2 z"/></g></g></svg><p class="cake-preview-caption">Así va tomando forma tu cake</p>`}
function currentCake(){return {model:selected.model,flavor:selected.flavor,filling:selected.filling,coverage:selected.coverage,meringue_color:selected.meringueColor,extra:selected.extra,price:selectedPrice()}}
function update(){let m=DATA.models.find(x=>x.id===selected.model);let total=selectedPrice();renderCakePreview();document.getElementById('total').textContent=money(cart.length?cart.reduce((sum,x)=>sum+x.price,0):total);let rows=[['Cake',m.name],['Sabor',selected.flavor]];if(m.kind==='custom'){rows.push(['Relleno',selected.filling],['Cobertura',selected.coverage]);if(selected.coverage==='Merengue incluido')rows.push(['Color',selected.meringueColor]);rows.push(['Extra',selected.extra])}document.getElementById('receipt').innerHTML=rows.map(x=>`<div class="receipt-row"><span>${esc(x[0])}</span><span>${esc(x[1])}</span></div>`).join('')+`<div class="receipt-row"><span>Este diseño</span><span>${money(total)}</span></div>`;document.getElementById('cart').innerHTML=cart.length?`<div class="receipt"><strong>Cakes añadidos (${cart.length})</strong>${cart.map((item,i)=>`<div class="receipt-row"><span>${esc(DATA.models.find(x=>x.id===item.model).name)} · ${esc(item.flavor)}</span><span>${money(item.price)} <button type="button" data-remove-cake="${i}" aria-label="Quitar cake ${i+1}">✕</button></span></div>`).join('')}</div>`:'';document.querySelectorAll('[data-remove-cake]').forEach(button=>button.addEventListener('click',()=>{cart.splice(Number(button.dataset.removeCake),1);update()}))}
function closeSuccessPopup(){document.getElementById('successOverlay').classList.remove('is-visible')}
function restartDesigner(){closeSuccessPopup();orderRequestId=crypto.randomUUID().replace(/-/g,'');cart=[];selected={model:'mini',flavor:'Vainilla',filling:'Fresa',coverage:'Merengue incluido',extra:'Sin extra',meringueColor:'Blanco'};document.getElementById('customerName').value='';document.getElementById('customerPhone').value='';document.getElementById('pickupDate').value='';document.getElementById('customerNote').value='';const notice=document.getElementById('notice');notice.className='notice';notice.textContent='';const button=document.getElementById('submitOrder');button.disabled=false;button.textContent='Crear ticket de compra';document.getElementById('addCake').disabled=false;modelCards();renderSteps();update();document.getElementById('configurador').scrollIntoView({behavior:'smooth',block:'start'})}
async function submit(){let notice=document.getElementById('notice'),button=document.getElementById('submitOrder');notice.className='notice';notice.textContent='';let name=document.getElementById('customerName').value.trim(),phone=document.getElementById('customerPhone').value.trim();if(!name||!phone){notice.className='notice error';notice.textContent='Escribe tu nombre y teléfono para generar el ticket.';return}button.disabled=true;button.textContent='Generando ticket…';const items=cart.length?cart:[currentCake()];let payload={csrf_token:CSRF,request_id:orderRequestId,items,total:items.reduce((sum,x)=>sum+x.price,0),cliente_nombre:name,cliente_telefono:phone,fecha_reserva:document.getElementById('pickupDate').value,nota:document.getElementById('customerNote').value.trim()};try{let r=await fetch('cakes_builder_api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),d=await r.json();if(!r.ok||d.status!=='success')throw new Error(d.msg||'No se pudo crear el ticket.');if(d.count!==null)setCakeCount(d.count);const reservationNumber='#'+esc(String(d.id).padStart(5,'0'));document.getElementById('successReservationNumber').textContent='Reserva '+reservationNumber;document.getElementById('successTicketLink').href='ticket_view.php?id='+encodeURIComponent(d.id)+'&token='+encodeURIComponent(d.tracking_token);document.getElementById('successTrackingLink').href='cakes_estado.php?token='+encodeURIComponent(d.tracking_token);document.getElementById('successOverlay').classList.add('is-visible');notice.className='notice';notice.textContent='';button.textContent='Reserva creada';document.getElementById('addCake').disabled=true;}catch(e){notice.className='notice error';notice.textContent=e.message;button.disabled=false;button.textContent='Crear ticket de compra'}}
modelCards();renderSteps();update();loadCakeCount();document.getElementById('submitOrder').addEventListener('click',submit);document.getElementById('addCake').addEventListener('click',()=>{if(cart.length>=20){const notice=document.getElementById('notice');notice.className='notice error';notice.textContent='Puedes añadir hasta 20 cakes por pedido.';return}cart.push(currentCake());update()});
</script>
</body>
</html>
